def transform(grid):
 h,w=len(grid),len(grid[0]); p=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==2]; q=[(r,c) for r in range(h) for c in range(w) if grid[r][c] not in (0,2)]
 if not p or not q:return [x[:] for x in grid]
 pc=((min(r for r,c in p)+max(r for r,c in p))/2,(min(c for r,c in p)+max(c for r,c in p))/2); qc=((min(r for r,c in q)+max(r for r,c in q))/2,(min(c for r,c in q)+max(c for r,c in q))/2)
 if abs(qc[1]-pc[1])>=abs(qc[0]-pc[0]): d=(0,1 if qc[1]>pc[1] else -1)
 else:d=(1 if qc[0]>pc[0] else -1,0)
 out=[x[:] for x in grid]
 for r,c in p:out[r][c]=0
 for r,c in p:
  rr,cc=r+d[0],c+d[1]
  if 0<=rr<h and 0<=cc<w:out[rr][cc]=2
 return out
